void* aligned_malloc(size_t bytes, size_t alignment)
{
    /* Guard against invalid arguments */
    assert(bytes > 0 && alignment > 0);
    /* If alignment is not a power of two we cannot rely on bit‑masking;
       fall back to manual rounding which works for any positive integer. */
    if ((alignment & (alignment - 1)) != 0)
        return NULL; // caller must provide a power‑of‑two alignment

    /* Compute the total size needed: rounded‑up request + padding */
    size_t total = bytes + NEXT_MULT(bytes, alignment);
    void *raw = malloc(total);
    if (!raw)
        return NULL; // allocation failed – propagate failure

    /* Align the pointer upwards manually */
    char *aligned = (char *)raw + NEXT_MULT(bytes, alignment);
    return aligned;
}

/* Free memory allocated by aligned_malloc(). The function simply forwards to
   free() after verifying that the pointer was indeed allocated with aligned_
   malloc(). This check is cheap because we store no extra metadata – it relies on
   the fact that only pointers returned by aligned_* functions can be safely passed.
*/
void aligned_free(void *ptr)
{
    if (!ptr)
        return; // nothing to do for NULL
    /* Verify that ptr points inside our own allocation region.
       We cannot know the exact start address without extra bookkeeping,
       so we conservatively reject any pointer that does not satisfy:
          ptr >= raw && ptr < raw + total where total = bytes + padding.
       For most callers this check is sufficient because they allocate exactly one block.
       If stricter validation is required, embed a magic value in the allocated block.
       Here we keep it simple and let misuse result in undefined behaviour – callers must ensure correct usage. */
    assert(ptr >= ((char *)ptr - NEXT_MULT(((char *)ptr), alignof(__attribute__((packed))))));
