/*
 * Memory arena (bump allocator) implementation.
 *
 * The arena works as a simple bump pointer: each allocation returns a
 * pointer to the next free byte after the previously allocated region.
 * Resetting discards all previously allocated memory; creating a sub‑arena
 * simply allocates another block from the original base.
 */
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

/* Arena descriptor */
typedef struct {
    void *base;          /* start of current allocation region */
    size_t   size;       /* total bytes allocated in this arena */
    size_t   used;       /* bytes currently in use */
} arena_t;

/* Helper to allocate from an existing arena */
static void *arena_alloc(arena_t *a, size_t n)
{
    if (n > a->size - a->used) {
        fprintf(stderr, "allocation request exceeds remaining space\n");
        exit(EXIT_FAILURE);
    }
    void *ptr = (char *)a->base + a->used;
    a->used += n;
    return ptr;
}

/* Allocate an entire new sub‑arena from the original base */
static void *arena_subarena(arena_t *a)
{
    if (a->base == NULL) {
        fprintf(stderr, "no base allocated yet\n");
        exit(EXIT_FAILURE);
    }
    /* Allocate enough space for one block plus its header metadata */
    size_t block = sizeof(void *) + sizeof(size_t); // pointer + size field
    void *new_base = realloc(a->base,
                               ((char *)a->base + a->used + block));
    if (!new_base) {
        fprintf(stderr, "realloc failed while creating sub‑arena\n");
        exit(EXIT_FAILURE);
    }
    char *ptr = (char *)new_base + ((char *)a->base + a->used);
    *(size_t *)ptr = block; // store block header for later free
    char **header = (char **)ptr;
    header[0] = new_base; // first element points back to new base
    header[1] = sizeof(*header); // second element holds total size of this sub‑arena
    return ptr;
}

/* Public API ---------------------------------------------------------- */
void init_arena(arena_t *a)
{
    memset(a, 0, sizeof(*a));
}

void reset_arena(arena_t *a)
{
    if (a->base == NULL) return; // nothing to reset
    free((void *)a->base);
    memset((void *)a, 0, sizeof(*a));
}

void create_subarenas(arena_t *parent)
{
    if (!parent || parent->base == NULL) return;
    void **headers = malloc((parent->used / sizeof(void*)) *
                           sizeof(*headers));
    if (!headers) { perror("malloc"); exit(EXIT_FAILURE); }

#if defined(__GNUC__) && __GNUC__ >= 7 && !defined(__clang__)
#pragma GCC diagnostic push
#pragma GCC diagnostic ignored "-Wstringop-overflow"
#endif
for (size_t i = 0; i < parent->used / sizeof(void*); ++i) {
#if defined(__GNUC__) && __GNUC__ >= 7 && !defined(__clang__)
#pragma GCC diagnostic pop
#endif
headers[i] = parent->base + i;
}
for (size_t i = 0; i < parent->used / sizeof(void*); ++i)
{
#if defined(__GNUC__) && __GNUC__ >= 7 && !defined(__clang__)
#pragma GCC diagnostic push
#pragma GCC diagnostic ignored "-Wstringop-overflow"
#endif
headers[i] += sizeof(*(headers[i]));
}
for (size_t i = 0; i < parent->used / sizeof(void*); ++i)
{
#if defined(__GNUC__) && __GNUC__ >= 7 && !defined(__clang__)
#pragma GCC diagnostic pop
#endif
headers[i] += sizeof(*(headers[i]));
}
free((void *)parent);
parent->base = headers[0];
parent->size = headers[1];
