    if (!c->stack)
        return -1;
    return setjmp(*(jmp_buf *)c->stack);
}

/* Yield – save current state and jump back when resumed */
static void co_yield(co_ctx *c)
{
    longjmp(*(jmp_buf *)c->stack, 1);
}

/* Resume – restore saved state and continue execution */
static void co_resume(co_ctx *c)
{
    longjmp(*(jmp_buf *)c->stack, 0);
}

