     * unaligned load which is slower but still correct on modern CPUs. */
    if (((uintptr_t)src & 0xF) == 0)
        return _mm_load_si128((const __m128i *)src);
    else {
        __m128i lo = _mm_loadu_si128((const __m128i *)src);
        __m128i hi = _mm_loadu_si128((const __m128i *)(src + 4));
        return _mm_unpacklo_epi64(lo, hi);
    }
}

static inline uint64_t dot_product(const uint64_t *a,
                                    const uint64_t *b)
{
    const size_t N = sizeof(uint64_t); // N == 8 for this problem
    const size_t VEC = N / sizeof(__m128i); // VEC == 4 (process four vectors)
    __m128i sum = _mm_setzero_si128();
    size_t i = 0;

    /* Process full vectors in groups of four */
    for (; i + VEC <= N; i += VEC * sizeof(__m128i)) {
        /* Load four vectors (each holds two elements per lane) */
        __m128i vec0 = load_vec(&a[i]);
        __m128i vec1 = load_vec(&a[i + VEC]);
        __m128i vec2 = load_vec(&b[i]);
        __m128i vec3 = load_vec(&b[i + VEC]);

        /* Shuffle to interleave low/high halves */
        vec0 = _mm_shufflelo(vec0, shuffleMask[0]);
        vec0 = _mm_shufflehi(vec0, shuffleMask[0]);
        vec0 = _mm_shufflelo(vec0, shuffleMask[3]);
        vec0 = _mm_shufflehi(vec0, shuffleMask[3]);

        vec1 = _mm_shufflelo(vec1, shuffleMask[0]);
        vec1 = _mm_shufflehi(vec1, shuffleMask[0]);
        vec1 = _mm_shufflelo(vec1, shuffleMask[3]);
        vec1 = _mm_shufflehi(vec1, shuffleMask[3]);

