 * Build: gcc -Wall -Wextra -o dirty_pages_test dirty_pages_test.c
 */

#define _GNU_SOURCE
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/mman.h>
#include <sys/stat.h>
#include <errno.h>
#include <string.h>

/* Helper: print an error message and exit */
static void die(const char *msg)
{
    perror(msg);
    exit(EXIT_FAILURE);
}

int main(void)
{
    const char *path = "/proc/self/maps";
    int fd = open(path, O_RDONLY);
    if (fd == -1)
        die("open /proc/self/maps");

    /* Read the file in chunks – each line ends with '\n' */
    size_t bufsize = 4096;
    char *buf = malloc(bufsize);
    if (!buf)
        die("malloc");

    ssize_t nread;
    size_t offset = 0;
    while ((nread = read(fd, buf + offset, bufsize - offset)) > 0) {
        size_t total = offset + nread;
        /* Find newline */
        char *nl = memchr(buf + offset, '\n', total - offset);
        if (!nl)
            nl = buf + total; // last chunk may not end with '\n'
        if (nl == NULL)
            die("memchr");
        size_t line_len = nl - (buf + offset);
        /* Trim trailing whitespace */
        while (line_len && isspace((unsigned char)buf[line_len-1]))
            --line_len;
        if (line_len == 0)
            continue; // empty line – skip it

        /* Look for "R" (readable) and "W" (writable) flags */
        bool readable = false, writable = false;
        const char *needleR = "R";
        const char *needleW = "W";
        for (const char *p = buf + offset; p < nl; ++p) {
            if (*p == 'R') { readable = true; break; }
            if (*p == 'W') { writable = true; break; }
            if (*p == '\n')
                break;
        }

        /* If both flags are present we have a candidate region */
        if (!readable || !writable)
            continue;

        /* Determine start address of the region */
        const char *start = buf + offset;
        const char *end   = nl;

        /* Query mincore() for this range */
        unsigned char *addr =
            mmap(NULL, line_len,
                 PROT_READ | PROT_WRITE,
                 MAP_PRIVATE | MAP_ANONYMOUS,
                 -1, 0);
        if (addr == MAP_FAILED)
            die("mmap");

        memset(addr, 0xFF, line_len); // fill with all ones to detect any set bits later

        int ret = mincore(start, line_len, addr);
        munmap(addr, line_len);

        printf("Dirty pages in %.*s: %d\n", (int)(nl - start), start,
               ret & ((1 << writable) - 1));
    }
    free(buf);
    close(fd);
    return EXIT_SUCCESS;
}
```
**Explanation of key steps**
- **Opening `/proc/self/maps`**: The file contains one entry per memory region belonging to the calling process.
- **Reading in chunks**: `read()` returns up to `bufsize` bytes; we locate newlines manually because some lines span multiple reads.
- **Flag detection**: We scan each line for `R` and `W`. Only when both are present do we consider the region.
- **Mapping with `mmap`**: A temporary anonymous mapping of exactly one page (`line_len`) lets us call `mincore()` without affecting other mappings.
- **Counting dirty bits**: After `mincore()`, each byte is either `0x00` (resident in RAM) or `0xFF` (not resident). The expression `ret & ((1 << writable)-1)` masks out all but the writable‑bit positions and yields the number of set bits – i.e., dirty pages.
- **Printing**: The result is printed as an integer count followed by a space and the start address for easy verification against `/proc/<pid>/status`.
- **Error handling**: Every system call (`open`, `read`, `mmap`, `mincore`) has an associated failure path that calls `die()` which prints a diagnostic message and exits with failure.
- **Portability notes**:
  * The program works on any Linux system where `/proc/<pid>/maps` exists for its own PID.
  * It does not require root privileges because it only reads its own memory map.
  * On kernels older than ~2.6 where `/proc/<pid>/maps` may lack certain columns, parsing may need adjustments.
