/* Simple shared counter */
static _Atomic int shared_counter = 0;

/* Atomic CAS helper – returns true on success */
static inline bool atomic_cas_int(int *target, int expected, int desired)
{
    return atomic_compare_exchange_strong_explicit(target, &expected,
                                                   desired,
                                                   memory_order_acq_rel,
                                                   memory_order_acquire);
}

/* Looped CAS that updates *target from old to new */
static inline bool cas_loop(int *target, int old, int new)
{
    while (!atomic_cas_int(target, old, new)) {
        /* If we fail because another thread changed the value,
           retry with the observed value.
           This is the classic "retry" pattern for lock‑free ops. */
        old = *target;   /* fetch current value */
    }
    return true;        /* success */
}

/* Test driver */
int main(void)
{
    int initial = 5;
    int final   = 10;
    bool ok;

    printf("Initial counter: %d\n", shared_counter);

    /* Attempt to set counter from initial to final using CAS loop */
    ok = cas_loop(&shared_counter, initial, final);
    assert(ok && "CAS should succeed when target matches expected");

    printf("Final counter after successful CAS: %d\n", shared_counter);

    /* Verify that the final value matches expectation */
    assert(shared_counter == final && "Counter did not reach expected value");

    printf("CAS test passed.\n");
    return 0;
}
