/* ---------------------------------------------------------------
 * Custom fixed‑size slab allocator (64‑byte chunks)
 * --------------------------------------------------------------- */
#include <stddef.h>
#include <stdint.h>
#include <stdlib.h>

/* Size of each chunk – must be power‑of‑two for masking */
#define CHUNK_SIZE 64U

/* Header stored at the beginning of each chunk */
typedef struct {
    uint8_t   tag;      /* identifier for debugging / debugging builds */
    uint8_t   pad[7];   /* align to 8‑byte boundary for cache line */
    uint16_t  next;     /* index of next free chunk in the pool */
} __attribute__((aligned(8))) chunk_header;

/* Payload area – exactly CHUNK_SIZE bytes */
typedef struct {
    uint8_t data[CHUNK_SIZE];
} __attribute__((aligned(8))) chunk;

/* Pool descriptor – holds the base address and total number of chunks */
typedef struct {
    void *base;          /* start of contiguous memory region */
    size_t   count;      /* number of chunks allocated */
} slab_pool;

/* ---------------------------------------------------------------
 * Allocation API
 * --------------------------------------------------------------- */
static inline int slab_init(slab_pool *pool, size_t total)
{
    if (total == 0 || total % CHUNK_SIZE != 0)
        return -1; /* invalid configuration */

    pool->base = malloc(total);
    if (!pool->base)
        return -1;

    pool->count = total / CHUNK_SIZE;
    return 0;
}

static inline void slab_destroy(slab_pool *pool)
{
    free(pool->base);
}

static inline int slab_push(slab_pool *pool, void **out)
{
    if (pool->count == 0)
        return -1; /* no space left */

    chunk *c = (chunk *)((uint8_t *)pool->base + pool->count * CHUNK_SIZE);
    c->next = pool->count - 1;          /* link into free list (LIFO) */
    c->tag = 'A';                       /* unique tag for debugging */
    c->pad[0] = c->pad[7] = '\0';

    *out = c;
    pool->count--;
    return 0;
}

static inline int slab_pop(slab_pool *pool, void **in)
{
    if (pool->count == 0)
