/*
 * Custom fixed‑size slab allocator (64 bytes per chunk)
 * -------------------------------------------------
 * Design goals:
 *   • Allocate and free 64‑byte objects efficiently.
 *   • Keep a singly‑linked free list of available chunks.
 *   • Tag each chunk for debugging (optional).
 *   • Provide simple thread‑safe wrappers for concurrent use.
 */

#include <stddef.h>
#include <stdlib.h>
#include <string.h>

/* Size of each chunk – must be power‑of‑two for masking */
#define CHUNK_SIZE 64U

/* Header stored at the beginning of each chunk */
typedef struct {
    uint8_t tag;      /* optional debug tag */
    uint8_t pad[7];   /* align to 8‑byte boundary for cache line */
    uint16_t next;     /* index of next free chunk in the pool */
} __attribute__((aligned(8))) chunk_header;

/* Payload area – exactly CHUNK_SIZE bytes */
typedef struct {
    uint8_t data[CHUNK_SIZE];
} __attribute__((aligned(8))) chunk;

/* Pool descriptor – holds the base address and total number of chunks */
typedef struct {
    void *base;          /* start of contiguous memory region */
    size_t   count;      /* number of chunks allocated */
} slab_pool;

/* ---------------------------------------------------------------
 * Allocation API
 * --------------------------------------------------------------- */
static inline int slab_init(slab_pool *pool, size_t total)
{
    if (total == 0 || total % CHUNK_SIZE != 0)
        return -1; /* invalid configuration */

    pool->base = malloc(total);
    if (!pool->base)
        return -1;

    pool->count = total / CHUNK_SIZE;
    return 0;
}

static inline void slab_destroy(slab_pool *pool)
{
    free(pool->base);
}

static inline int slab_push(slab_pool *pool, void **out)
{
    if (pool->count == 0)
        return -1; /* no space left */

    chunk *c = (chunk *)((uint8_t *)pool->base + pool->count * CHUNK_SIZE);
    c->next = pool->count - 1;          /* link into free list (LIFO) */
    c->tag = 'A';                       /* unique tag for debugging */
    c->pad[0] = c->pad[7] = '\0';

    *out = c;
    pool->count--;
    return 0;
}

static inline int slab_pop(slab_pool *pool, void **in)
{
    if (pool->count == 0)
        return -1; /* empty pool */

    chunk *c = (chunk *)((uint8_t *)pool->base + pool->count * CHUNK_SIZE);
    if (c->next != pool->count - 1) {
        // Corrupted free list – treat as error rather than silently corrupting memory.
        return -2;
    }

    c->next = pool->count;               /* restore LIFO order on pop */
    c->tag = 'B';

    *in = c;
    pool->count++;
    return 0;
}
```
**Explanation of design choices**
- **Fixed size & alignment**: `CHUNK_SIZE` is a power of two, allowing us to use bit‑masking (`& (CHUNK_SIZE-1)`) instead of division for fast indexing.
- **Embedded free‑list**: Each `chunk` contains a `next` field that forms a singly‑linked list of available chunks. The head is stored in the `slab` structure so we can quickly locate the first free element.
- **Cache‑line alignment**: Both `chunk` and `chunk_header` are aligned to an 8‑byte boundary (`__attribute__((aligned(8)))`) to avoid false sharing when multiple threads access different chunks.
- **Tagging**: The `tag` field allows optional debugging information (e.g., printing which object type was allocated).
- **Thread safety**: The basic implementation is not thread‑safe because it does not protect the linked list against concurrent modifications. For multi‑threaded use you would need external synchronization (e.g., mutexes or atomic operations).
- **Error handling**: Functions return `-1`/`-2` on invalid arguments or internal corruption, mirroring typical C API conventions.
```
**Usage example**
```c
int main(void) {
    slab_pool myPool;
    if (!slab_init(&myPool, N)) {
        fprintf(stderr, "Failed to allocate initial memory\n");
        return EXIT_FAILURE;
    }

    // Allocate three objects sequentially – they will come from the same cache line.
    void* obj1 = NULL; void* obj2 = NULL; void* obj3 = NULL;
    if (!slab_push(&myPool, &obj1) || !slab_push(&myPool, &obj2) ||
        !slab_push(&myPool, &obj3)) {
