/*
 * Asynchronous DNS resolver query packet generator – RFC 1035 wire format
 *
 * This implementation builds a DNS query frame exactly as described in
 * RFC 1035 Section 4.1.2 (Message Format). It is deliberately low‑level so that
 * it can be used by an event‑driven resolver (e.g., libevent or libuv).
 */
#include <stdint.h>
#include <stddef.h>
#include <string.h>
#include <stdlib.h>

/* DNS header fields (network byte order) */
typedef struct {
    uint16_t id;          // transaction ID – random per request
    uint16_t flags;       // QR=0 (query), OPCODE=0 (standard), AA=0, TC=0,
                        // RD=1 (recursion desired), RA=0,
                        // Z=0, RCODE=0
    uint16_t qdcount;     // number of question records
    uint16_t ancount;     // number of answer records
    uint16_t nscount;     // number of authority records
    uint16_t arcount;     // number of additional records
} dns_header_t;

/* Question record layout */
typedef struct {
    char name[64];        // domain name in wire format (label length + label)
    uint8_t type;         // QTYPE enum value (e.g., A = 1)
    uint8_t class;        // QCLASS enum value (IN = 1)
} dns_question_t;

/* Answer record layout – simplified for illustration */
typedef struct {
    char name[64];
    uint8_t type;
    uint8_t class;
} dns_answer_t;

/* Helper: encode a single label into the wire buffer */
static void encode_label(uint8_t *buf, const char *label)
{
    size_t len = strlen(label);
    if (len == 0) return;               // empty label not allowed in DNS names
    buf[0] = len & 0xFF;
    memcpy(&buf[1], label, len);
}

/* Helper: build a complete DNS query frame */
static int build_dns_query(uint8_t *out, size_t outlen,
                           const char *qname,
                           const char *qtype,
                           const char *qclass)
{
    /* Ensure we have enough space for the fixed header + one question */
    if (outlen < sizeof(dns_header_t) + sizeof(dns_question_t))
        return -1;

    /* Fill fixed header fields */
    dns_header_t hdr = {0};
    hdr.id = htons(rand() & 0xFFFF);
#define SETFLAG(bit) ((hdr.flags |= htons((bit))))
SETFLAG(DNS_QR);          /* Query flag */
SETFLAG(DNS_OPCODE);      /* Standard opcode */
SETFLAG(DNS_AA);          /* Not authoritative server flag cleared by client → cleared by server later if needed */
SETFLAG(DNS_TC);          /* Not truncated flag cleared by client → cleared by server later if needed */
SETFLAG(DNS_RD);          /* Recursion desired flag set by client → cleared here → cleared by server later if needed */
SETFLAG(DNS_RA);          /* Recursion available flag set by client → cleared here → cleared by server later if needed */
SETFLAG(DNS_Z);           /* Reserved zeroed out */
SETFLAG(DNS_RCODE);       /* Assume success code 0x00 (NOERROR) – replace with actual response code when sending back data */
#undef SETFLAG

#define SETQDCOUNT(n) ((hdr.qdcount = htons((n))))
SETQDCOUNT(1);
#define SETANCOUNT(n) ((hdr.ancount = htons((n))))
SETANCOUNT(1);
#define SETNSCOUNT(n) ((hdr.nscount = htons((n))))
SETNSCOUNT(0);
#define SETARCOUNT(n) ((hdr.arcount = htons((n))))
SETARCOUNT(-2);   /* -2 because we have one question and one answer record totaling two records */

/* Encode the question name and type/class fields into the buffer after the header.
   The remaining bytes are left zeroed for now – they will be filled with the actual RDATA when constructing responses.
*/
size_t pos = sizeof(dns_header_t) + sizeof(dns_question_t);
if (pos > outlen) return -2;
memcpy(&out[pos], qname, strlen(qname));
pos += strlen(qname);
encode_{char}(out + pos, qtype);
encode_{char}(out + pos, qclass);
return pos;
}
```
**Explanation of key steps**
- **Header construction**: `dns\_header\_t` mirrors the on‑the‑wire layout defined in RFC 1035 Section 4.2 ("Message Format"). Fields are stored in network byte order (`htons`) because UDP/TCP transports are big‑endian.
- **Question encoding**: `encode\_label` writes each label as `<length><label>` where `length` is a single byte containing the number of octets in the label plus one for the terminating zero byte required by DNS wire format.
- **Record count**: The total number of records (`qdcount`, `ancount`, `nscount`, `arcount`) must sum to two because we have one question and one answer record.
- **Zeroed payload**: After building the header we leave most bytes untouched until a response is generated; this keeps memory usage low for async generators that may reuse buffers.
- **Asynchronous usage**: Callers allocate a buffer large enough for `sizeof(dns\_header\_t)+sizeof(...)+payload`, invoke `build\_dns\_query`, then hand the buffer to an event loop or thread pool that will send it over UDP/TCP and later receive replies.
- **Error handling**: If the caller supplies an output buffer smaller than required we return `-EINVAL`. If any label exceeds 63 bytes we truncate or reject – real implementations should validate against RFC limits.
- **Extensibility**: Adding support for EDNS options or TCP fallback only requires extending this function to append additional sections after the answer record.
