    size_t page = sysconf(_SC_PAGESIZE);
    size_t size = page * 4;               // allocate 4 pages (4 × page)
    void *addr;

    /* Create an unnamed shared memory object */
    int fd = shm_open(region_name, O_CREAT | O_RDWR, 0600);
    if (fd == -1) {
