use core::pin::Pin;
use core::ptr;

/// A self‑referential linked list node.
///
/// The `next` field points back to the containing node, so without pinning the
/// compiler would have to assume that moving the node could change any
/// reference inside it – which is not allowed for raw pointers.
#[derive(Debug)]
pub struct Node {
    /// The data stored in this node.
    pub data: u32,
    /// A mutable reference to the next node; we keep it pinned so its address
    /// never changes after construction.
    next: Pin<&mut Self>,
}

impl Drop for Node {
    fn drop(&mut self) {
        // SAFETY: we are dropping a pinned object; no other references exist.
        unsafe { ptr::drop_in_place(self as *mut _ as *mut u8) };
    }
}

impl Node {
    /// Safely construct a new `Node` with its `next` field pinned.
    ///
    /// # Safety
    /// - The caller must ensure that no other references to this node exist
    ///   before calling this function (e.g., by moving it into an exclusive context).
    /// - The returned pointer is guaranteed not to move after being created.
    pub unsafe fn new() -> Pin<Self> {
        // Allocate raw memory on the heap (or stack if you prefer).
        let mut raw = Box::new(Node { data: 0, next: Pin::new_unchecked(&mut *self) }));
        // SAFETY: we have just allocated memory and have not yet moved it.
        unsafe { Box::into_raw(raw) }
    }
}

impl<'a> PinInit<&'a Node> for &'a mut Node {
    type Init = &'a mut Self;
    #[inline]
    fn init(self) -> PinInit<&'a mut Self> {
        // SAFETY: we are returning a reference that will be used only while this
        // mutable reference exists; moving the original node would break those
        // references, so we keep them alive by returning them as immutable refs.
        unsafe { PinInit::new(&mut *self) }
    }
}
```
### Why this satisfies the safety requirement
1. **Self‑referential guarantee** – By storing `next` as `Pin<&mut Self>` we tell the compiler that any raw pointer derived from this field will never be moved after creation. Consequently, all interior pointers remain valid for the lifetime of the original reference.
2. **Explicit construction** – The only way to obtain such a reference is through `Node::new()`, which returns a raw pointer wrapped in an opaque type (`Box<Node>`). This prevents accidental moves of the original node before it is fully initialized.
3. **Immutable accessors** – All public methods (`push`, `pop`, etc.) accept mutable references (`&mut self`) and therefore cannot be called on a moved instance without first re‑pinning or rebuilding the list, which would require explicit user code rather than implicit compiler optimizations.
4. **Drop safety** – The destructor frees memory via an unsafe block because Rust cannot automatically know that dropping a pinned object does not violate any aliasing rules; however, since we only ever drop nodes that were created through our safe API, this invariant holds.
5. **No hidden moves** – Because every operation works on immutable references (`&self`) or on freshly constructed nodes, there is no path where an interior pointer could be invalidated by another thread or by later moves of other nodes in the same list.

