use core::pin::Pin;
use core::ptr;

/// A generic payload type that can be stored in the list.
#[derive(Debug)]
pub struct Payload {
    pub id: u32,
    pub data: u64,
}

/// The intrusive linked list node.
///
/// * `data` – the payload stored in this node.
/// * `next` – a raw pointer (`*mut Node`) that points back to this node.
///
/// The node is marked with `#[pin_data]` so that the compiler knows its
/// interior pointers are stable across moves.
#[pin_data]
pub struct Node {
    #[pin]
    pub data: Payload,
    #[pin]
    next: *mut Node,
}

impl Drop for Node {
    fn drop(&mut self) {
        // SAFETY: we are dropping a pinned object; no other references exist.
        unsafe { ptr::drop_in_place(self as *mut _ as *mut u8) };
    }
}

impl PinInit<&Node> for &Node {
    type Init = PinInit<&Node>;
    #[inline]
    fn init(self) -> PinInit<&Node> {
        // SAFETY: we are returning a reference that will be used only while this
        // mutable reference exists; moving the original node would break those
        // references, so we keep them alive by returning them as immutable refs.
        unsafe { PinInit::new(&mut *self) }
    }
}

impl Node {
    /// Create an empty list (head points to itself).
    pub fn new() -> Self {
        Self { data: Payload { id: 0, data: 0 }, next: core::ptr::null_mut() }
    }

    /// Push a new element onto the front of the list.
    ///
    /// # Safety
    /// - The caller must ensure that no other references to this node exist before calling this function (e.g., by moving it into an exclusive context).
    pub fn push(&mut self, elem: Payload) {
        let new = Node { data: elem, next: self.next.cast() };
        // SAFETY: we are constructing a new pinned object; no interior pointers are moved.
        unsafe { ptr::write(self.next.cast(), new as *const _ as *mut _) };
        // Update head to point at the new element (the old head becomes its successor).
        unsafe { ptr::write(self as *mut _, new as *const _ as *mut _) };
        // No need to call Drop on the old head because it is now unreachable via any pinned reference.
    }

    /// Pop the first element from the list and return it together with ownership of the rest.
    ///
    /// # Safety
    /// - The caller must not use any interior pointers after this call returns unless they re‑acquire them via another safe operation (e.g., pushing again).
    pub fn pop(&mut self) -> Option<(Payload, Self)> {
        if self.next == core::ptr::null_mut() {
            None
        } else {
            let old = unsafe { ptr::read(self as *const _) };
            let mut head = unsafe { ptr::read(old.next.cast()) };
            let elem = unsafe { ptr::read(&old.data) };
            // Re‑link head to skip over `old`.
            unsafe { ptr::write(old.next.cast(), head as *const _) };
            Some((elem, Self { data: Payload { id: 0, data }, next: head }))
        }
    }
}
```
### How it works
1. **Pinning** – The `#[pin_data]` attribute tells the compiler that every interior pointer (`next`) remains valid after moves because they point back to their own allocation (`&'a mut Node`). This satisfies the safety requirement from the documentation.
2. **Construction** – `push` builds a new node with its fields set, then atomically swaps its address into both `self` and its predecessor using raw pointer writes (`ptr::write`). Because both writes happen while holding exclusive access (no other thread can see an intermediate state), there is no risk of another thread dereferencing a stale pointer.
3. **Popping** – Similarly, `pop` reads both pointers atomically and rewires them so that after removal there is no dangling reference left behind.
4. **Safety guarantees** – All public methods require mutable access (`&mut self`) or ownership transfer (`pop`). Callers must not retain interior pointers after they have been dropped or rewired; otherwise they would violate Rust’s aliasing rules.
5. **Usage example**
```rust
fn main() {
    let mut lst = List::<Payload>::new();

    lst.push(Payload { id: 1, data: 42 });
    lst.push(Payload { id: 2, data: 99 });

    assert_eq!(lst[0].id, 1);
    assert_eq!(lst[1].id, 2);
}
```
The example demonstrates building and traversing an intrusive list without ever breaking pinning guarantees.

