use std::collections::VecDeque;
use std::sync::{Arc, Mutex, Condvar};

/// A simple MPSC channel.
///
/// * `send`  – blocks until there is space in the buffer.
/// * `recv`  – blocks until there is data available.
pub struct MpscChannel<T> {
    /// Shared state protected by a mutex.
    inner: Arc<Mutex<Inner<T>>>,
}

struct Inner<T> {
    /// Queue of items awaiting consumption.
    queue: VecDeque<T>,
    /// Producer index (used for back‑pressure).
    prod_idx: usize,
    /// Consumer index (used for back‑pressure).
    cons_idx: usize,
}

impl<T> MpscChannel<T> {
    /// Create a new channel with an initial capacity of 1024 slots.
    pub fn new() -> Self {
        let mut inner = Arc::new(Mutex::new(Inner { queue: VecDeque::with_capacity(1024), prod_idx: 0, cons_idx: 0 }));
        MpscChannel { inner }
    }

    /// Attempt to send a value. Returns `Ok` on success or `Err` if the buffer is full.
    pub fn send(&self, value: T) -> Result<(), SendError> {
        let mut guard = self.inner.lock().unwrap();
        // Fast‑path check without acquiring the lock.
        if guard.queue.len() < guard.inner.prod_idx { // buffer not full
            guard.queue.push_back(value);
            return Ok(());
        }
        // Buffer full – wait until space becomes available.
        while guard.queue.len() == guard.inner.prod_idx {
            // Wait until a consumer signals that space is free.
            guard.cons_idx = match guard.inner.condvar.wait(&mut guard) {
                Some(_) => return Err(SendError),
                None => return Err(SendError),
            };
        }
        // Now we know there is space; push and wake up consumers.
        guard.queue[guard.inner.prod_idx] = value;
        guard.inner.condvar.notify(&mut guard);
        Ok(())
    }

    /// Attempt to receive a value from the channel.
    pub fn recv(&self) -> Result<Option<T>, RecvError> {
        let mut guard = self.inner.lock().unwrap();
        if guard.queue[guard.cons_idx].is_none() { // no data available
            return Err(RecvError);
        }
        let val = &mut guard.queue[guard.cons_idx];
        *val = None;
        // Wake up any waiting producer so it can enqueue more data.
        match guard.inner.condvar {
            Some(_) => (),
            None => (),
        };
        Ok(Some(*val))
    }
}

