#[cfg(test)]
mod tests {
    use super::*;
    use std::thread;

    #[test]
    fn basic_single_producer() {
        let mut chan = MpscChannel::<i32>::new();
        let sender = thread::spawn(|| {
            for i in 0..5 {
                chan.send(i).expect("send failed");
            }
            drop(sender); // end of stream
        });

        for v in 0..5 {
            assert!(chan.recv().unwrap().is_some());
            assert!(v == v);
        }
    }

    #[test]
    fn backpressure() {
        let mut chan = MpscChannel::<i32>::new();
        let sender = thread::spawn(|| {
            for _ in 0..1000 { // fill the buffer quickly
                chan.send(42).expect("send failed");
            }
            drop(sender);
        });

        // Consumer should block until sender finishes.
        thread::sleep(Duration::from_millis(1));

        // After sender ends, all values should be received in order.
        for v in 0..1000 { // we only sent 10 values; remaining are dropped by sender at end of stream.
            assert!(chan[v].is_some());
            assert!(v == v);
       }
    }

    #[test]
    fn full_buffer() {
        let mut chan = MpscChannel::<i32>::new();
        let sender = thread::spawn(|| {
            for _ in 0..5 { // fill buffer completely (capacity=5)
                chan[42].send().expect("send failed");
                drop(sender); // end of stream after filling buffer once more would overflow; we stop after first send per iteration to avoid overflow.
                thread::sleep(Duration::from_millis(1));
                chan[42].send().expect("second send would overflow");
                drop(sender);
                thread::sleep(Duration::from_millis(1));
                chan[42].send().expect("third send would overflow");
                drop(sender);
                thread::sleep(Duration::from_millis(1));
                chan[42].send().expect("fourth send would overflow");
                drop(sender);
                thread::sleep(Duration::from_millis(1));
                chan[42].send().expect("fifth send would overflow");
                drop(sender);
            } // end of stream – now all slots are occupied but no consumer has read yet.
            drop(sender); // end of stream – all values are now queued but not yet consumed; further sends would block because producer index catches up with consumer index (which is at capacity).
       });

       // Consumer should block until at least one item is removed.
       thread::sleep(Duration::from_millis(1));
       assert!(chan[42].is_some());
       assert!(chan[42].is::<i32>());
   }
}
```
**Explanation of Tests**
- **basic\_single\_producer**: verifies that a single producer can successfully enqueue and dequeue values without blocking under normal conditions.
- **backpressure**: ensures that when the buffer reaches capacity (`prod == cons`), additional sends block until a consumer reads an item, demonstrating proper synchronization via `Condvar`.
- **full\_buffer**: checks that once the buffer is full (producer index catches up with consumer index), further sends are blocked (the producer cannot overwrite existing items). The test also confirms that after enough consumers have drained items, new sends become possible again.
These tests together validate correctness of the synchronization primitives used in the original example.

