use std::io::{Read, Seek};
use std::net::IpAddr;

/// A zero‑copy packet abstraction.
///
/// * The parser works on an immutable reference to raw bytes (`&[u8]`).
/// * It does **not** allocate or copy data; it only reads from the slice.
/// * Lifetimes are tied to the original buffer so the parser cannot outlive it.
pub trait Packet {
    /// Total length of the packet in bytes.
    fn len(&self) -> usize;

    /// Returns a slice of the payload after stripping any link‑layer headers.
    fn payload(&self) -> &[u8];

    /// Returns an iterator over all IP addresses found in the payload.
    fn ip_addresses(&self) -> impl Iterator<Item = IpAddr> + '_ {
        self.payload().iter().filter(|ip| ip.is_ipv4() || ip.is_ipv6())
    }
}

/// Zero‑copy implementation for IPv4 packets.
pub struct Ipv4Packet<'a> {
    // SAFETY: we guarantee that `buf` lives at least as long as any reference
    // returned by this parser because we store it inside the struct.
    buf: &'a [u8],
}

impl<'a> Packet for Ipv4Packet<'a> {
    fn len(&self) -> usize { self.buf.len() }
    fn payload(&self) -> &[u8] { &self.buf[20..] } // 20 = Ethernet header size (14) + IPv4 header (20)
}

impl<'a> Packet for Ipv4Packet<'a> {
    fn ip_addresses(&self) -> impl Iterator<Item = IpAddr> + '_ {
        let payload = self.payload();
        let mut iter = payload.iter();
        while let Some(ip) = iter.next() {
            if ip.is_ipv4() { yield IpAddr::V4(ip); }
            if ip.is_ipv6() { yield IpAddr::V6(ip); }
        }
        // No explicit termination – iterator ends when slice is exhausted.
    }
}

// Example usage:
fn main() {
    // Assume we have a raw packet buffer from a socket read operation.
    let raw: &[u8] = /* ... */;

    // Parse into an immutable view – no allocation occurs.
    let pkt: &Ipv4Packet<'_> = unsafe { std::slice::from_raw_parts(raw, raw.len()) };

    // Access fields without copying.
    println!("Length: {}", pkt.len());
    println!("Payload starts at offset 20");

    // Iterate over IP addresses safely because we hold a reference to `raw`.
    for addr in pkt.ip_addresses() {
        println!("IP address {:?}", addr);
    }
}
```
**Why this is zero‑copy**
1. The parser never creates new buffers; it only takes references (`&[u8]`) into the original slice.
2. All methods (`len`, `payload`, `ip_addresses`) operate on those references, so no memory is allocated or copied during parsing.
3. The lifetime `'a` ties the parser’s existence to the original buffer, preventing dangling references even if later code stores pointers elsewhere (as long as they respect `'a`).
4. By using traits we keep parsing logic decoupled from specific packet formats, enabling reuse across different protocols (e.g., TCP, UDP) while preserving safety guarantees.

