use std::alloc::{GlobalAlloc, Layout};
use std::mem;
use libc::{c_void, malloc, free};

/// A minimal wrapper around the C `malloc`/`free` functions.
struct MallocWrapper {
    /// The raw pointer returned by `malloc`.
    ptr: *mut c_void,
}

impl MallocWrapper {
    fn new() -> Self {
        // Allocate a single byte; we will grow it manually.
        let ptr = unsafe { malloc(1) };
        if ptr.is_null() {
            panic!("malloc failed");
        }
        Self { ptr }
    }
}

impl Drop for MallocWrapper {
    fn drop(&mut self) {
        // Free the whole block in one call – this is safe because we own it.
        unsafe { free(self.ptr as *mut c_void) };
    }
}

// GlobalAlloc implementation that forwards to libc.
struct MyGlobalAlloc;

unsafe impl GlobalAlloc for MyGlobalAlloc {
    // The size of the allocation requested by the caller.
    unsafe fn alloc(&self, layout: Layout) -> *mut c_void {
        // Compute total size needed for this allocation (including alignment).
        let total = layout.size().checked_add(layout.align() - 1).ok_or(EINVAL)?;
        let aligned = total & !(layout.align() - 1);

        // Allocate raw memory from libc.
        let raw = unsafe { malloc(total) };
        if raw.is_null() {
            panic!("libc malloc failed");
        }

        // Wrap the raw pointer in our owning struct so we can free it later.
        let wrapper = MallocWrapper { ptr: raw };

        // Return a pointer that satisfies GlobalAlloc's contract – we simply cast.
        wrapper as *mut _ as *mut c_void
    }

    // Deallocate memory backed by libc.
    unsafe fn dealloc(&self, ptr: *mut c_void, layout: Layout) {
        let wrapper = ptr as *mut MallocWrapper;
        unsafe { free(wrapper.ptr as *mut c_void) };
    }
}
```
### How It Works
1. **Allocation** – `alloc` computes the total size needed for the requested layout (including alignment), allocates a raw block with `libc::malloc`, and wraps it in a `MallocWrapper` that implements `Drop`. This ensures the memory is automatically freed when the wrapper goes out of scope.
2. **Deallocation** – `dealloc` receives a pointer that was originally allocated via our wrapper; it frees it using `libc::free`.
3. **Trait Satisfaction** – By implementing both methods of `GlobalAlloc`, our type can be used wherever a global allocator is required (e.g., via `std::alloc::Layout::from_size_align`).
4. **Error Handling** – If either allocation or deallocation fails (`ptr == null()`), we panic with an informative message; in production code you might return an error instead.
5. **Safety Guarantees** – All unsafe blocks are confined to thin wrappers around well‑defined libc functions, and ownership is transferred to a Rust object (`MallocWrapper`) that guarantees cleanup via its own Drop implementation.

