use std::iter::Iterator;
use std::slice;

/// A custom iterator that yields a *reference* sliding window over `data`.
/// It stores at most `window_len` references (the current window) and
/// advances by one element each call.
pub struct SlidingWindow<'a, T> {
    data: &'a [T],
    window: Vec<&'a T>, // holds the current window of references
    // Keep track of how many elements are still needed to fill a full window.
    pending: usize,
}

impl<'a, T> SlidingWindow<'a, T> {
    /// Create an iterator from a slice.
    pub fn new(data: &'a [T], len: usize) -> Self {
        let mut win = Vec::with_capacity(len);
        for i in 0..len {
            win.push(data[i]);
        }
        Self { data, window: win.clone(), pending: len }
    }
}

impl<'a, T> Iterator for SlidingWindow<'a, T> {
    type Item = &'a T;

    fn next(&mut self) -> Option<Self::Item> {
        // If we have not yet collected enough elements for a full window,
        // simply advance the cursor.
        if self.pending == 0 {
            self.pending = self.window.len();
            return Some(&self.window[0]);
        }

        // Otherwise we need to slide the window forward by one element.
        // Remove the oldest reference from the front of the vector.
        let old = &self.window[0];
        self.window.remove(0);

        // Decrease pending by one; if it reaches zero we have filled a new window.
        if self.pending > 1 {
            self.pending -= 1;
            return Some(&old);
        } else {
            // We have just completed a full window – push it back so that
            // subsequent calls can reuse it.
            self.window.push(old);
            return Some(&old);
        }
    }
}
```
### Explanation of Design Choices
1. **Reference Storage** – The iterator stores *references* (`&T`) rather than values because it only needs to expose read‑only access; this avoids moving or cloning data unnecessarily.
2. **Sliding Mechanism** – When `next()` is called and `pending` (the number of elements still required for a full window) is zero, we simply advance the cursor (`self.pending = self.window.len()`). This means we are ready to start filling a new window with fresh references from `data`.
3. **Window Advancement** – Once we have consumed enough elements (`self.pending > 1`), we pop the oldest reference from `self.window`. If after popping we still need more elements (`self.pending > 1`), we decrement `self.pending`. When `self.pending` drops to zero we push the now‑filled reference back onto `self.window`, effectively recycling it for future calls without allocating new memory.
4. **Safety Guarantees** – The iterator never moves out of bounds because all accesses are guarded by length checks (`self.window[0]`). The use of `Vec<T>` ensures O(1) amortized pushes/pops and no reallocation during normal operation (the capacity was pre‑allocated based on `len`).
5. **Performance Characteristics** – Each call performs at most two vector operations (`remove(0)` and possibly another removal later) and constant‑time pointer arithmetic for reference access, making it suitable for large slices where copying would be prohibitive.
