/// Example usage:
///
/// ```rust
/// #[derive(ByteSize)]
/// struct MyStruct {
///     a: u8,
///     b: u16,
///     c: [u8; 4],
/// }
/// ```
///
/// The macro expands to an impl block containing a const function
/// `fn byte_size() -> usize`.
pub fn derive_byte_size(input: TokenStream) -> TokenStream {
    // 1️⃣ Parse the input token stream into an AST.
    let ast = parse_str::<syn::ItemStruct>(input);
    if let Some(item) = ast {
        // 2️⃣ Walk each field recursively.
        let byte_size: TokenStream = walk_fields(&item);
        // 3️⃣ Emit the const impl.
        quote! {
            impl ByteSize for #item {
                /// Returns the total size of this struct in bytes.
                ///
                /// This is computed at compile time using `std::mem::size_of`.
                const fn byte_size() -> usize {
                    #byte_size
                }
            }
        }
    } else {
        // If parsing fails we return an empty token stream so that compilation fails early.
        TokenStream::new()
    }
}

fn walk_fields(item: &syn::ItemStruct) -> TokenStream {
    let mut fields = Vec::new();
    item.fields.iter().for_each(|f| {
        // Skip unnamed fields – they are not part of the public API.
        if f.ident.is_none() { return; }
        let field = f.ident;
        // 4️⃣ Compute size of each field type.
        let size = match f.ty {
            syn::Type::Path(path) => match path.to_string() {
                "u8" => 1,
                "u16" => 2,
                "u32" => 4,
                "u64" => 8,
                _ => panic!("Unsupported primitive type in ByteSize derivation"),
            },
            syn::Type::Array(array) => array.elem.ty().unwrap().size(),
            syn::Type::Slice(_) | syn::Type::Tuple(_) | syn::Type::_ => panic!("Unsupported field type in ByteSize derivation"),
            _ => panic!("Unsupported field type in ByteSize derivation"),
        };
        fields.push(quote! { #field: #size });
    });
    // Recursively process nested structs/unions/enums.
    item.fields.iter().flat_map(|f| walk_fields(&f)).collect()
}
