    assert!(arr.len() >= 4);

    // Load four floats from memory using an unaligned load. This avoids UB
    // that would occur if we used `_mm_loadl`/`storel`.
    let vec = simd128::<f32>::from_slice(arr);

    // Perform element‑wise addition across all lanes.
    let add = _mm_add_ps(vec, vec);

    // Extract the scalar result from each lane. We could also sum directly
    // by converting back to a plain float vector and adding, but extracting is
    // clearer here.
    let scalar = add.extract::<f32>();

    // Convert back to a plain float vector so we can sum it safely.
    let total = simd128::<f32>::zeroed();
    total = total + scalar;

    total.to_vec()
}
