impl<T> Send for BlockingChannel<T> {}
impl<T> Sync for BlockingChannel<T> {}

impl<T> BlockingChannel<T> {
    /// Sends a task to all workers and returns when the last worker has taken it.
    pub fn send(&self, task: T) -> bool {
