        self.sender.send(task).is_ok()
    }
}

/// Worker implementation that receives tasks from the channel and executes them.
struct Worker {
    id: usize,
}

impl Worker {
    fn new(id: usize) -> Self { Self { id } }
}

impl Worker {
    fn run(&self) {
        // Receive tasks until the channel is closed by the main thread.
        while let Some(task) = self.receiver.recv() {
            worker_task(self.id);
            // After processing one task we can optionally send another if there are more pending tasks.
            // Here we simply block on recv again; in real code you might have multiple tasks queued.
        }
