use std::sync::{Arc, Mutex};
use std::thread;
use std::time::{Duration, Instant};
use crossbeam_channel::{Sender, Receiver};

/// A simple task that implements `FnOnce`.
#[derive(Clone)]
struct Task {
    fn: fn(),
}

/// Worker implementation that receives tasks from its own channel.
struct Worker {
    id: usize,
    // Shared state – one receiver per worker.
    receiver: Receiver<Task>,
}

impl Worker {
    fn new(id: usize) -> Self { Self { id: id } }
}

impl Worker {
    /// Starts a worker thread that continuously receives tasks.
    fn start(&self) -> thread::JoinHandle<()> {
        let mut handle = thread::spawn(move || {
            // Loop until the sender is closed.
            while let Some(task) = self.receiver.recv() {
                // Execute the task synchronously – this mirrors typical crossbeam usage where
                // each task is processed immediately after being received.
                self.fn_call();
            }
        });
        handle
    }
}

/// Main function that creates N workers and distributes tasks over crossbeam channels.
fn main() -> Result<(), Box<dyn std::error::Error>> {
    const NUM_WORKERS: usize = 4;
    const TASKS_PER_BATCH: usize = 100;

    // Create N workers.
    let mut workers = Vec::<Worker>::with_capacity(NUM_WORKERS);
    for i in 0..NUM_WORKERS {
        workers.push(Worker::new(i));
    }

    // Create two channels: one for sending tasks to workers, one for receiving results.
    let (sender_to_workers, receiver_from_workers): (Sender<Task>, Receiver<Task>) =
        crossbeam_channel::channel();

    // Spawn worker threads – each runs its own loop receiving from its sender.
    let handles = vec![workers[0].start(); workers[1..].iter().map(|w| w.start()).collect()];

    // Distribute tasks in batches to keep the system responsive while still respecting back-pressure.
    let mut next = 0usize;
    while !handles.is_empty() || next < NUM_WORKERS as usize {
        if handles.is_empty() && next < NUM_WORKERS as usize { next += 1; }
        let task = match next % NUM_WORKERS as usize { 0 => Task { fn_: () }, _ => Task { fn_: () }, };
        sender_to_workers.send(task).expect("failed to send task");
        next += 1;
        if handles[0].is_terminated() { break; } // graceful shutdown of idle workers
        thread::sleep(Duration::from_millis(5)); // give other workers time to pick up work
    }

    // Wait for all worker threads to finish before exiting.
    for h in handles { h?; }

    Ok(())
}
```
**Explanation of key parts**
- **`Task`** holds an immutable function pointer (`fn_: ()`) so each worker can execute it without capturing mutable state.
- **`Worker`** owns its own `Receiver`, ensuring no shared mutable state between workers; this avoids data races because each receiver pulls from its own internal queue managed by crossbeam.
