    greeting: Option<String>,
}

// ------------------------------------------------------------
// 2️⃣ Actor implementation – runs forever in its own task.
// ------------------------------------------------------------
struct GreeterActor;

impl GreeterActor {
    // Called by the runtime when the actor is created.
    fn handle(&self) -> Result<(), Box<dyn std::error::Error>> {
        // In a real program this would do work; here we just reply.
        let reply = Greeter { greeting: Some("Hello".to_string()) };
        // Send the reply back to the original sender.
        let _ = self.send(reply);
        Ok(())
    }
}

// ------------------------------------------------------------
// 3️⃣ Sender/Receiver pair – one per client connection.
// ------------------------------------------------------------
fn main() -> Result<(), Box<dyn std::error::Error>> {
    // Create a channel that can hold up to N messages (here N=1).
    let (tx, rx): mpsc::channel::<Greeter> = mpsc::channel::<Greeter>(1);
    let sender = tx.clone();
    let receiver = rx;

    // Spawn the actor on its own Tokio runtime.
    let actor_handle = tokio::spawn(async move {
        // Run an infinite loop handling incoming messages.
        while let Some(msg) = receiver.recv().await {
            // Process the message – for demonstration we just print it.
            println!("Received: {:?}", msg);
            // Send a response back using the same channel.
            sender.send(msg).await?;
        }
        Ok(())
    });

    // Example client code – send a greeting and wait for a reply.
    let client_tx = tx; // clone for sending from another task if needed
    let client_rx = rx;

    // Send a greeting from another task (or main thread).
    client_tx.send(Greeter { greeting: Some("World".to_string()) }).await?;

    // Receive the reply asynchronously using select! so we don't block on send().
    tokio::select! {
        msg = client_rx.recv().await => println!("Client received: {:?}", msg),
        _ => {}
    }

    // Wait for the actor to finish gracefully.
    drop(actor_handle);

    Ok(())
}
```
