// ConvertBytesToString creates a new Go string from a []byte without allocating
// a backing array. It works on Go 1.20+ where unsafe.String is available.
// The implementation uses unsafe.SliceData to obtain the underlying byte slice
// and then builds an unsafe.String with the same pointer, length, and capacity.
func ConvertBytesToString(b []byte) string {
    // Guard against nil input – converting nil to string yields "".
    if b == nil {
        return ""
    }
    // Ensure we have at least one byte; otherwise we cannot create a string.
    if len(b) == 0 {
        return ""
    }
    // Build an unsafe.String with the same pointer, length, and capacity.
    // The capacity must match len(b) because we are not creating a larger buffer.
    // This avoids extra allocations when the resulting string is later used.
    return unsafe.String((*byte)(unsafe.Pointer(&b[0])), uintptr(len(b)), uintptr(len(b)))
}
