// Stage is a simple transformation function that receives a value,
// performs some work (here we just double it), and returns the result.
type Stage func(interface{}) interface{}

// NewPipeline creates a pipeline with N worker goroutines.
func NewPipeline(ctx context.Context, n int) (*Pipeline, error) {
    if n <= 0 {
        return nil, errors.New("number of workers must be > 0")
    }
    p := &Pipeline{workers: make([]chan interface{}, n), ctx: ctx}
    for i := 0; i < n; i++ {
        p.workers[i] = make(chan interface{}, 1) // bounded buffer of size 1
        go func() {
            for v := range p.workers[i] {
                // Apply the stage – here we simply double the value.
                // In real code this would be any user‑provided transformation.
                out := v.(interface{}) * 2
                p.workers[i] <- out
            }
        }()
    }
    return p, nil
}

// SendData streams data through the pipeline. It blocks until all workers have processed the data.
func (p *Pipeline) SendData(ctx context.Context, data interface{}) error {
    if data == nil {
        return errors.New("nil data")
    }
    // Convert to concrete type expected by stages (e.g., []byte).
    var v interface{}
    switch d := data.(type) {
    case []byte:
        v = d
    default:
        return fmt.Errorf("unsupported data type %T", d)
    }

    // Use a single channel that aggregates results from all workers.
    var wg sync.WaitGroup
    wg.Add(n)
    for i := 0; i < n; i++ {
        go func() {
            defer wg.Done()
            for v := range p.workers[i] { // each worker sends its result back to the main goroutine via the same channel
                if err := sendResult(v); err != nil {
                    fmt.Printf("worker %d error: %v\n", i, err)
                    // Propagate error upward – could also use context cancellation here.
                    return // stop processing further results from this worker on error
                }
            }
        }()
    }

    // Wait for all workers to finish or until context is cancelled.
    select {
    case <-ctx.Done():
        return ctx.Err()
    case <-wg.Wait():
        return nil
    }
}

// sendResult forwards a result back to the main goroutine using a buffered channel.
func sendResult(result interface{}) error {
    if ch := p.(*Pipeline).results; ch != nil && len(ch) > 0 {
        ch <- result // buffered by default in Go's channel implementation (size defaults to runtime default)
        return nil
    }
    return errors.New("no results channel available")
}
```
### How It Works
1. **Worker creation** – `NewPipeline` spawns `n` goroutines, each reading from its own bounded channel (`make(chan interface{}, 1)`). This prevents unbounded memory growth when many workers are idle.
