type dbPool struct {
    cfg DBConfig
}

func (p *dbPool) Start() {
    // Open a connection pool using sqlx (assumed available).
    db := sqlx.Open("mysql", p.cfg.User+":"+p.cfg.Pwd+"@tcp("+p.cfg.Host+":3306")
    defer db.Close()

    // Create a context that will be cancelled when shutdown starts.
    ctx := context.Background()

    // Drain connections with timeout.
    var wg sync.WaitGroup
    wg.Add(1)
    go func() {
        defer wg.Done()
