package pubsub

import (
    "errors"
    "regexp"
    "sync"
)

// Event represents a payload delivered to subscribers.
type Event struct {
    Data interface{}
}

// Subscriber holds a callback that will be invoked when an event matches its subscription.
type Subscriber struct {
    Topic   Topic          // exact topic name or regex pattern
    Callback func(Event) // invoked with the matching event
}

// Publisher is responsible for delivering events to all matching subscribers.
type Publisher struct {
    mu      sync.RWMutex // protects subscription map and delivery path
    topics  map[Topic][]regexPattern // key: topic string or compiled regex; value: slice of compiled patterns
}

// NewPublisher creates a new Pub/Sub instance.
func NewPublisher() *Publisher {
    return &Publisher{topics: make(map[Topic][]regexPattern)}
}

// Subscribe adds a subscriber to the specified topic. Regex patterns are compiled once per subscription.
func (p *Publisher) Subscribe(topic Topic, pattern string) error {
    if pattern == "" {
        return errors.New("empty pattern")
    }
    re := regexp.MustCompile(pattern)
    p.mu.Lock()
    defer p.mu.Unlock()
    if _, exists := p.topics[topic]; !exists {
        p.topics[topic] = make([]regexPattern, 0)
    }
    p.topics[topic] = append(p.topics[topic], re)
    return nil // registration complete; actual delivery happens on Publish()
}

// Publish delivers an event to all subscribers whose topic matches the event's topic name or any of its regex patterns.
func (p *Publisher) Publish(event Event) error {
