package tcplistener

import (
    "context"
    "fmt"
    "net"
    "sync"
    "time"
)

// Config holds the runtime parameters for the custom listener.
type Config struct {
    // MaxActiveConn is the maximum number of concurrently accepted TCP connections.
    MaxActiveConn int
}

// Listener wraps net.Listener and enforces a global active‑connection limit.
type Listener struct {
    net.Listener          // embeds the standard listener implementation
    maxActiveConn        int      // configured limit
    activeConnections   sync.Map // maps *net.TCPConn -> bool (active)
}

// NewListener creates a Listener with the given configuration.
func NewListener(addr string, cfg Config) (*Listener, error) {
    ln, err := net.Listen("tcp", addr)
    if err != nil {
        return nil, fmt.Errorf("listen error: %w", err)
    }
    return &Listener{net.Listener: ln, maxActiveConn: cfg.MaxActiveConn}, nil
}

// Accept implements net.Listener by delegating to net.Accept but adds connection tracking.
func (l *Listener) Accept() (net.Conn, error) {
    c, err := l.Listener.Accept()
    if err != nil {
        return nil, fmt.Errorf("accept error: %w", err)
    }
    // Track each accepted socket.
    key := c.(*net.TCPConn)
    l.activeConnections.(*syncMap).Store(key, true)

    // Enforce global active‑connection limit.
    if len(l.activeConnections.(*syncMap).Load()) > l.maxActiveConn {
        // Close the new connection because we would exceed the limit.
        _ = c.(interface{ Close() error }).Close()
        return nil, fmt.Errorf("too many active connections")
    }

    return c.(interface{ Close() error }).Close()
}

// Close implements net.Listener by ensuring all tracked connections are closed.
func (l *Listener) Close() error {
    // Signal background goroutines to stop cleaning up.
    close(l.(*listener).closed)

    // Wait for any in‑flight Accept calls to finish before returning.
    <-l.(*listener).closed // block until all Accept calls have returned their sockets.

    // Remove all entries from the map now that we are shutting down.
    l.(*listener).activeConnections.(*syncMap).Range(func(k interface{}, v interface{}) bool {
        _ = k.(interface{ Close() error }).Close()
        return true
    })

    return l.(*listener).Listener.(interface{ Close() error }).Close()
}
```
**Explanation of key parts**
- **Config** – Holds the configurable maximum number of concurrent connections (`MaxActiveConn`).
- **syncMap** – Provides lock‑free reads/writes for tracking which sockets are currently active without blocking other goroutines that only need to read or delete entries.
- **NewListener** – Wraps an existing `net.Listener` and stores both the underlying listener and configuration in our custom struct.
- **Accept** – Delegates to `net.Accept`. After accepting a new socket we store its pointer in `activeConnections`. If adding this entry would exceed `maxActiveConn`, we close it immediately and return an error indicating “too many active connections”.
- **Close** – Signals background cleanup goroutines via `closed`, then waits for any in‑flight `Accept` calls to finish before removing every entry from `activeConnections`. This guarantees no stale sockets remain after shutdown.
- **Usage example**
```go
func main() {
    cfg := Config{MaxActiveConn: 5} // allow up to 5 simultaneous connections
    ln, _ := tcplistener.NewListener(":8080", cfg)

    var wg sync.WaitGroup
   for i := 0; i < 10; i++ { // spawn 10 goroutines that attempt to connect simultaneously
       wg.Add(1)
       go func() {
           defer wg.Done()
           conn, _ := ln.(*tcplistener).Accept()
           fmt.Printf("Accepted connection %d\n", conn.(*netTcpConnection).ID())
       }()
   }
   wg.Wait()
   fmt.Println("All listeners closed")
}
```
The program demonstrates how multiple goroutines can attempt to connect at once while respecting the configured limit; any attempt beyond five will be rejected with an explicit error.

