    # Load second operand into RBX (second argument)
    movq %rsi, %rbx        # %rsi holds *b (second argument)
    # Perform addition – RBX is added to RAX (carry handled automatically)
    addq %rbx, %rax         # Result ends up in RAX (also returned via rax)
