class AsyncEventLoop:
    def __init__(self):
        # Create a selector that monitors all file descriptors we care about.
        self._selector = selectors.DefaultSelector()
        # Store sockets that are currently registered.
        self._sockets: dict[int, socket.socket] = {}

    # Register a socket for read/write events.
    def register(self, fd: int, events: int) -> None:
        self._selector.register(fd, events)
        self._sockets[fd] = socket.socket(socket.AF_INET6 if fd == 4 else socket.AF_INET,
                                         socket.SOCK_STREAM)
        self._sockets[fd].setblocking(False)  # make it non‑blocking

    # Unregister a socket – remove from selector and close it.
    def unregister(self, fd: int) -> None:
        if fd in self._sockets:
            del self._sockets[fd]
            self._selector.unregister(fd)
            try:
                self._sockets[fd].close()
            except Exception as e:
                raise RuntimeError("Failed to close socket %d" % fd) from e

    # Poll for ready events using selectors.
    def poll(self) -> Generator[tuple[int, int], None]:
        """Yield (fd, mask) pairs where mask indicates readable/writable."""
        while True:
            try:
                events = list(self._selector.select())
            except KeyboardInterrupt:
                raise  # let the caller decide whether to exit
            for fd, mask in events:
                if fd in self._sockets:
                    yield (fd, mask)
                    continue
                else:
                    raise RuntimeError("Unknown file descriptor %d" % fd)

    # Run the event loop until an exception or explicit stop.
    def run(self):
        try:
            while True:
                for ready in self.poll():
                    # For demonstration we simply print the result.
                    print("Ready:", ready)
                    # In a real application you would dispatch to handlers here.
                    pass
        except KeyboardInterrupt:
            print("\nExiting event loop.")
