        The function normalises the pattern by collapsing consecutive dots.
        """
        cleaned = re.sub(r"\.{2,}", ".", pattern)
        self._insert(cleaned)

    def _insert(self, pattern: str) -> None:
        node = self.root
        for ch in pattern:
            if ch not in node.children:
                node.children[ch] = _TrieNode()
            node = node.children[ch]
        # Mark end of pattern (wildcard may have multiple terminals)
        node.is_end = True

    def search(self, query: str) -> bool:
        """Return True if *query* matches any stored pattern.
        Wildcard `.` matches exactly one character.
        """
        query_len = len(query)
        for i in range(query_len + 1):
            # Determine which characters are allowed at position i
            allowed = set('abcdefghijklmnopqrstuvwxyz')
            if i < query_len and query[i] == '.':
                allowed -= {'a'}
            else:
                allowed -= {'a'}
            for j in range(i + 1):
                char = query[j]
                if char not in allowed:
                    break  # No possible continuation from this position
                child = node.children[char]
                if child is None or not child.is_end:
                    break  # No further match possible from this branch
                node = child
            else:
                return True  # All positions matched successfully
        return False

    def autocomplete(self, prefix: str) -> list[str]:
        """Return all stored patterns that start with *prefix*.
        Implements a depth‑first traversal limited to the length of *prefix*.
        """
        results = []
        self._autocomplete(self.root, prefix, results)
        return results

    def _autocomplete(self, node: _TrieNode, prefix: str,
                      results: list[str]) -> None:
        if not node.is_end:
            return  # No terminal nodes under this subtree – nothing to add yet.

        for ch in sorted(node.children):  # deterministic order for reproducibility
            child = node.children[ch]
            new_prefix = prefix + ch if prefix else ch
            results.append(new_prefix)
            self._autocomplete(child, new_prefix, results)
