def evaluate_ast(root: Expr) -> float:
    """Recursively evaluate an expression tree.
    Returns a float result; raises ValueError on malformed trees.
    """
    # Base case: literal values are returned directly.
    if isinstance(root, Literal):
        return float(root.value)
    if isinstance(root, Variable):
        return float(root.name)
    if isinstance(root, BinaryOp):
        # Evaluate children first.
        left_val = evaluate_ast(root.left)
        right_val = evaluate_ast(root.right)
        # Perform operation respecting precedence (addition/subtraction before multiplication/division).
        if root.op == '+':
            return left_val + right_val
        elif root.op == '-':
            return left_val - right_val
        elif root.op == '*':
            return left_val * right_val
        elif root.op == '/':
            # Guard against division by zero.
            if right_val == 0:
                raise ValueError('Division by zero')
            return left_val / right_val
        else:
